def lockup(cls="", title="FIXIA Architecte"):
    """Logo horizontal : symbole + mot-symbole, couleur héritée (currentColor)."""
    return ('<svg class="%s" viewBox="0 0 2990 845" role="img" aria-label="%s"><path fill="currentColor" d="%s"/>'
            '<g transform="translate(1262 253) scale(1.6) translate(-13 -970)"><path fill="currentColor" d="%s"/></g></svg>') % (cls, title, SYMBOL_D, WORD_D)


def stacked(cls="", title="FIXIA"):
    return ('<svg class="%s" viewBox="0 0 1102 1182" role="img" aria-label="%s"><path fill="currentColor" d="%s"/>'
            '<path fill="currentColor" d="%s"/></svg>') % (cls, title, SYMBOL_D, WORD_D)


def symbol(cls="", fill="currentColor"):
    return '<svg class="%s" viewBox="0 0 1102 845" aria-hidden="true" focusable="false"><path fill="%s" d="%s"/></svg>' % (cls, fill, SYMBOL_D)
